function setup() {
	createCanvas(600, 600);
}


function draw() {
	background("beige")

	const swX = width * 0.1;
	const swY = swX * 0.5;

	noStroke()
	for (let x = 0; x < width; x += swX * 2) {
		fill(random(["grey", "white", "yellow", 64]))
		rect(x, 0, swX, height)
	}

	for (let y = 0; y < height; y += swY * 2) {
		fill(random(["grey", "white", "yellow", 64]))
		rect(0, y, height, swY)
	}


	// noLoop() removed for animation
}
